fn frame(t: i32) {
    host::display::clear(0x0f1013);
    if host::display::state_get(0) == 0 {
        let h: i32 = host::http::get("https://www.rust-lang.org/", 26);
        host::display::state_set(1, h);
        if h < 0 {
            host::display::state_set(0, 3);
        } else {
            host::display::state_set(0, 1);
        }
    }
    let h2: i32 = host::display::state_get(1);
    if host::display::state_get(0) == 1 {
        let r: i32 = host::http::ready(h2);
        if r == 1 {
            host::display::state_set(0, 2);
        } else if r < 0 {
            host::display::state_set(0, 3);
        }
    }
    let phase: i32 = host::display::state_get(0);
    if phase == 1 {
        host::display::draw_string(180, 240, "LOADING", 0xaa7700, 2);
    } else if phase == 2 {
        let total: i32 = host::http::body_lines(h2);
        let mut maxoff: i32 = total - 14;
        if maxoff < 0 {
            maxoff = 0;
        }
        let down: i32 = host::display::pointer_down();
        let prev: i32 = host::display::state_get(3);
        host::display::state_set(3, down);
        if down == 1 && prev == 0 {
            let mut off: i32 = host::display::state_get(2);
            if host::display::pointer_y() < 256 {
                off = off - 1;
            } else {
                off = off + 1;
            }
            if off < 0 {
                off = 0;
            }
            if off > maxoff {
                off = maxoff;
            }
            host::display::state_set(2, off);
        }
        let off2: i32 = host::display::state_get(2);
        for i in 0..14 {
            host::http::draw_line(h2, off2 + i, 8, 40 + i * 14, 0xcccccc, 1);
        }
        host::display::fill_rect(0, 0, 512, 24, 0x1a1d22);
        host::display::draw_string(8, 8, "PAGER  TOP=UP  BOTTOM=DOWN", 0x888888, 1);
        host::display::draw_number(300, 6, off2 + 1, 0xffffff, 1);
        host::display::draw_string(330, 8, "OF", 0x888888, 1);
        host::display::draw_number(354, 6, total, 0xffffff, 1);
    } else {
        host::display::draw_string(150, 240, "FETCH FAILED", 0xbb3333, 2);
    }
    host::display::present();
}
